public class IteratorUtils_collatedIterator_TriageGen0Test {











    @Test
    public void testCollatedIterator_DescendingOrder() {
        // Testing with a reverse comparator
        Comparator<Integer> comparator = (a, b) -> b.compareTo(a);
        Iterator<Integer> it1 = Arrays.asList(1, 5, 9).iterator();
        Iterator<Integer> it2 = Arrays.asList(2, 6, 10).iterator();

        Iterator<Integer> result = IteratorUtils.collatedIterator(comparator, it1, it2);

        // Expected order: 10, 9, 6, 5, 2, 1 (based on the comparator logic)
        // Wait, if comparator is b.compareTo(a), then 10 is "smaller" than 1.
        // Let's check the logic: collatedIterator uses comparator to decide which comes first.
        // If comparator.compare(10, 9) < 0, 10 comes first.
        // With (a,b) -> b.compareTo(a): compare(10, 9) -> 9.compareTo(10) -> -1.
        // So 10 is "less than" 9.

        List<Integer> expected = Arrays.asList(10, 9, 6, 5, 2, 1);
        List<Integer> actual = IteratorUtils.toList(result);

        assertEquals("The collated iterator should respect the provided comparator", expected, actual);
    }


}

